var agora = new Date();
var dow = agora.getDay();
var diasAteSeg = dow === 0 ? 6 : dow - 1;
var domSemanaAnt = new Date(agora);
domSemanaAnt.setDate(agora.getDate() - diasAteSeg - 1);
var segSemanaAnt = new Date(domSemanaAnt);
segSemanaAnt.setDate(domSemanaAnt.getDate() - 6);
var fmt = function(d) {
  return String(d.getDate()).padStart(2, '0') + '/' +
    String(d.getMonth() + 1).padStart(2, '0') + '/' +
    d.getFullYear();
};
var fmtPG = function(d) {
  return d.getFullYear() + '-' +
    String(d.getMonth() + 1).padStart(2, '0') + '-' +
    String(d.getDate()).padStart(2, '0');
};
var datas = [];
var cursor = new Date(segSemanaAnt);
while (cursor <= domSemanaAnt) {
  datas.push(fmt(cursor));
  cursor.setDate(cursor.getDate() + 1);
}
return [{
  json: {
    dataRef: fmt(segSemanaAnt) + ' a ' + fmt(domSemanaAnt),
    datasSemanaBR: datas.map(function(dt) { return "'" + dt + "'"; }).join(','),
    semanaInicio: fmtPG(segSemanaAnt),
    semanaFim: fmtPG(domSemanaAnt)
  }
}];

var items = $input.all();
var dataRef = $('01S - Calcular Periodo Semanal').first().json.dataRef || '';
var semanaLabel = dataRef;

if (items.length === 0 || (items.length === 1 && items[0].json._semEventos) || !items[0].json.placa) {
  return [{ json: { _semEventos: true, dataRef: semanaLabel } }];
}

var grouped = {};
for (var i = 0; i < items.length; i++) {
  var d = items[i].json;
  var filial = d.filial_operacional || 'DESCONHECIDA';
  if (!grouped[filial]) grouped[filial] = [];
  grouped[filial].push(d);
}

var results = [];
var filiais = Object.keys(grouped);
for (var fi = 0; fi < filiais.length; fi++) {
  var filial = filiais[fi];
  var evs = grouped[filial];
  var total = evs.length;
  if (total < 5) continue;
  var vels = evs.map(function(e) { return parseFloat(e.velocidade_registrada) || 0; }).filter(function(v) { return v > 0; });
  var velMax = vels.length > 0 ? Math.max.apply(null, vels) : 0;
  var velMedia = vels.length > 0 ? Math.round((vels.reduce(function(s,v){return s+v;},0) / vels.length) * 100) / 100 : 0;
  var porPlaca = {};
  for (var ei = 0; ei < evs.length; ei++) {
    var e = evs[ei];
    if (!porPlaca[e.placa]) porPlaca[e.placa] = { qtd: 0, velMax: 0, modelo: e.modelo || '', provedor: e.provedor_rastreador || '3STEC' };
    porPlaca[e.placa].qtd++;
    var v = parseFloat(e.velocidade_registrada) || 0;
    if (v > porPlaca[e.placa].velMax) porPlaca[e.placa].velMax = v;
  }
  var tabelaPlacas = Object.keys(porPlaca).map(function(p) {
    return { placa: p, qtd: porPlaca[p].qtd, velMax: porPlaca[p].velMax, modelo: porPlaca[p].modelo, provedor: porPlaca[p].provedor };
  }).sort(function(a,b){return b.qtd-a.qtd;}).slice(0,15);
  var topOc = evs.slice().sort(function(a,b){
    return (parseFloat(b.velocidade_registrada)||0)-(parseFloat(a.velocidade_registrada)||0);
  }).slice(0,10).map(function(e){
    return { placa: e.placa, velocidade: e.velocidade_registrada, data: e.data_hora_alerta,
      local: (e.cidade||'')+(e.estado?'/'+e.estado:''), origem: e.provedor_rastreador || '3STEC' };
  });
  var porDia = {};
  for (var ei2 = 0; ei2 < evs.length; ei2++) {
    var dt = evs[ei2].data_hora_alerta ? String(evs[ei2].data_hora_alerta).substring(0,10) : 'desconhecido';
    if (!porDia[dt]) porDia[dt] = 0;
    porDia[dt]++;
  }
  var breakdownDias = Object.keys(porDia).sort().map(function(dia){ return { dia: dia, qtd: porDia[dia] }; });
  var placaDias = {};
  for (var ei3 = 0; ei3 < evs.length; ei3++) {
    var dt2 = evs[ei3].data_hora_alerta ? String(evs[ei3].data_hora_alerta).substring(0,10) : 'desconhecido';
    if (!placaDias[evs[ei3].placa]) placaDias[evs[ei3].placa] = {};
    placaDias[evs[ei3].placa][dt2] = true;
  }
  var recidivistas = Object.keys(placaDias).filter(function(p){ return Object.keys(placaDias[p]).length >= 3; })
    .sort(function(a,b){ return Object.keys(placaDias[b]).length - Object.keys(placaDias[a]).length; })
    .map(function(p){
      return { placa: p, diasAtivos: Object.keys(placaDias[p]).length,
        totalAlertas: porPlaca[p] ? porPlaca[p].qtd : 0,
        velMax: porPlaca[p] ? porPlaca[p].velMax : 0,
        modelo: porPlaca[p] ? porPlaca[p].modelo : '',
        provedor: porPlaca[p] ? porPlaca[p].provedor : '3STEC' };
    });
  var piorKeys = Object.keys(porPlaca).sort(function(a,b){
    return porPlaca[b].qtd !== porPlaca[a].qtd ? porPlaca[b].qtd - porPlaca[a].qtd : porPlaca[b].velMax - porPlaca[a].velMax;
  });
  var resumo = '';
  if (piorKeys.length > 0) {
    var piorPlaca = piorKeys[0];
    var piorDados = porPlaca[piorPlaca];
    var evGrave = evs.filter(function(e){ return e.placa === piorPlaca; })
      .sort(function(a,b){ return (parseFloat(b.velocidade_registrada)||0)-(parseFloat(a.velocidade_registrada)||0); })[0];
    var local = evGrave ? ((evGrave.endereco ? evGrave.endereco + ', ' : '') + (evGrave.cidade||'') + (evGrave.estado?'/'+evGrave.estado:'')).trim().replace(/^,\s*/,'') : 'local nao registrado';
    var nivel = piorDados.velMax >= 120 ? 'CRITICO' : piorDados.velMax >= 100 ? 'ALTO' : 'MODERADO';
    resumo = nivel + ' - Veiculo ' + piorPlaca + ' (' + piorDados.provedor + ') com ' + piorDados.qtd + ' alerta(s) na semana. Pico de ' + piorDados.velMax + ' km/h' + (local ? ' em ' + local : '') + '.';
  } else {
    resumo = 'OK - Nenhum veiculo com padrao critico identificado.';
  }

  // E-mails centralizados do Banco de Dados (DW)
  var emailDestinoFinal = evs[0].email_destino_db || 'torredecontrole@gritsch.com.br';
  var ccParts = [];
  if (evs[0].email_cc_db) ccParts.push(evs[0].email_cc_db);
  if (evs[0].cc_regional_db) ccParts.push(evs[0].cc_regional_db);
  if (evs[0].cc_global_db) ccParts.push(evs[0].cc_global_db);
  var emailCCFinal = ccParts.join(';').split(/[;,]+/).map(function(s){return s.trim();}).filter(Boolean).filter(function(v,i,a){return a.indexOf(v)===i;}).join(',');

  results.push({ json: {
    filial: filial, dataRef: semanaLabel, totalEventos: total, velMax: velMax, velMedia: velMedia,
    tabelaPlacas: tabelaPlacas, topOcorrencias: topOc, breakdownDias: breakdownDias,
    recidivistas: recidivistas, resumoAnalitico: resumo,
    emailDestino: emailDestinoFinal, emailCC: emailCCFinal,
    consolidadoDestinatarios: evs[0].consolidado_destinatarios_db || 'jefferson@gritsch.com.br',
    consolidadoCC: evs[0].consolidado_cc_db || 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br'
  }});
}
if (results.length === 0) return [{ json: { _semEventos: true, dataRef: semanaLabel } }];
return results;

// ===========================================================================
// 13S - Gerar HTML Email Semanal  (identidade visual Grupo Gritsch, v1.0)
//
// Mesma paleta e componentes do relatorio diario ("18 - Gerar HTML Email").
// Ver aquele arquivo para o mapeamento secao-a-secao do design system.
//
// DUAS SECOES QUE O DIARIO NAO TEM, porque so fazem sentido numa janela de
// 7 dias: "Volume por dia" (barra por dia da semana) e "Reincidentes"
// (placa com alerta em 3 dias ou mais). Os dados ja vem prontos do node
// 11S em d.breakdownDias / d.recidivistas — so a renderizacao mudou aqui.
//
// Filiais com menos de 5 eventos na semana nao chegam a este node (o node
// 11S descarta antes) — e por isso que o rodape avisa esse filtro.
// ===========================================================================

const d = $json;

const fmtNum = (n) => String(n ?? 0).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmtDec = (n) => String(n ?? 0).replace('.', ',');

const AZUL      = '#213035';
const VINHO     = '#8E2E2F';
const ALERTA    = '#FA1126';
const CRITICO   = '#5A181C';
const ATENCAO   = '#E8A33D';
const POSITIVO  = '#13880D';
const CINZA     = '#4E4D4D';
const BORDA     = '#BFBFBF';
const REGUA     = '#E2E2E2';
const FUNDO     = '#F2F2F2';
const BRANCO    = '#FFFFFF';

const FONTE = "'Roboto Condensed','Arial Narrow',Arial,sans-serif";

const LOGO_ESCURA = 'https://gritsch.com.br/wp-content/uploads/2022/03/logomarca-1_gritsch-1.png';
const LOGO_BRANCA = 'https://gritsch.com.br/wp-content/uploads/2023/07/logo_branca1080.png';

const corVelocidade = (v) => (v >= 140 ? CRITICO : v >= 120 ? ALERTA : ATENCAO);

const badgeOrigem = (p) => {
  const prov = p || '3STEC';
  const cor = prov === '3STEC' ? AZUL : prov === 'OMNILINK' ? CINZA : VINHO;
  return '<span style="display:inline-block;padding:3px 8px;font-size:11px;font-weight:700;'
       + 'color:' + BRANCO + ';background:' + cor + ';border-radius:4px;'
       + 'font-family:' + FONTE + '">' + prov + '</span>';
};

const th = (txt, align) =>
  '<th style="padding:10px 12px;text-align:' + (align || 'left') + ';font-size:12px;'
  + 'font-weight:700;text-transform:uppercase;color:' + BRANCO + ';background:' + VINHO + ';'
  + 'font-family:' + FONTE + '">' + txt + '</th>';

const td = (conteudo, align, cor, peso) =>
  '<td style="padding:10px 12px;border-bottom:1.6px solid ' + REGUA + ';font-size:13px;'
  + 'text-align:' + (align || 'left') + ';color:' + (cor || CINZA) + ';'
  + 'font-weight:' + (peso || '400') + ';font-family:' + FONTE + '">' + conteudo + '</td>';

const boxKpi = (rotulo, valor, unidade, corNumero) =>
  '<td width="33%" valign="top" style="padding:0 8px">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + BRANCO + ';'
  + 'border:1.6px solid ' + BORDA + ';border-radius:12px"><tr><td style="padding:14px 20px">'
  + '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + ';'
  + 'font-family:' + FONTE + '">' + rotulo + '</div>'
  + '<div style="font-size:26px;font-weight:700;color:' + (corNumero || AZUL) + ';margin-top:4px;'
  + 'font-family:' + FONTE + '">' + valor
  + (unidade ? '<span style="font-size:13px;font-weight:400;color:' + CINZA + '"> ' + unidade + '</span>' : '')
  + '</div></td></tr></table></td>';

const faixaSecao = (titulo, corFaixa) =>
  '<tr><td style="padding:26px 32px 0">'
  + '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td style="background:' + (corFaixa || VINHO) + ';border-radius:10px 10px 0 0;padding:9px 20px;'
  + 'font-size:14px;font-weight:700;color:' + BRANCO + ';font-family:' + FONTE + '">'
  + titulo + '</td></tr></table></td></tr>';

const tabela = (cabecalhos, linhas) =>
  '<tr><td style="padding:0 32px">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="border:1.6px solid ' + BORDA + ';'
  + 'border-top:none;border-radius:0 0 12px 12px;background:' + BRANCO + '">'
  + '<tr>' + cabecalhos + '</tr>' + linhas + '</table></td></tr>';

// --- Caixa de resumo (destaque da semana) ----------------------------------
// O node 11S monta o texto sem emoji (MODERADO/ALTO/CRITICO/OK em texto puro,
// diferente do diario que ainda usa emoji) — aqui so precisa mapear para cor.
const resumoTxt = String(d.resumoAnalitico || '');
const ehOk = /^OK/.test(resumoTxt);
const nivelResumo = ehOk ? 'Sem padrão crítico'
  : /CRITICO/.test(resumoTxt) ? 'Crítico'
  : /ALTO/.test(resumoTxt)    ? 'Alto'
  : 'Moderado';
const corResumo = ehOk ? POSITIVO
  : /CRITICO/.test(resumoTxt) ? ALERTA
  : ATENCAO;
const corpoResumo = resumoTxt.replace(/^(OK|MODERADO|ALTO|CRITICO)\s*[-—]\s*/, '').trim();

const boxResumo = corpoResumo
  ? '<tr><td style="padding:22px 32px 0">'
    + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';'
    + 'border-left:4px solid ' + corResumo + ';border-radius:0 8px 8px 0">'
    + '<tr><td style="padding:16px 22px">'
    + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:' + CINZA + ';'
    + 'font-family:' + FONTE + '">Destaque da semana · ' + nivelResumo + '</div>'
    + '<div style="font-size:14px;color:' + CINZA + ';margin-top:7px;line-height:1.7;'
    + 'font-family:' + FONTE + '">' + corpoResumo + '</div>'
    + '</td></tr></table></td></tr>'
  : '';

// --- Volume por dia (barra horizontal) -------------------------------------
const bd = d.breakdownDias || [];
let secDias = '';
if (bd.length > 0) {
  const maxQtd = Math.max.apply(null, bd.map(x => x.qtd));
  let rowsDias = '';
  for (const linha of bd) {
    const pct = maxQtd > 0 ? Math.round((linha.qtd / maxQtd) * 100) : 0;
    const diaFmt = String(linha.dia || '').split('-').reverse().join('/');
    rowsDias += '<tr>'
      + '<td style="padding:7px 12px;font-size:12px;color:' + CINZA + ';white-space:nowrap;'
      + 'font-family:' + FONTE + '">' + diaFmt + '</td>'
      + '<td style="padding:7px 12px;width:100%">'
      + '<div style="background:' + REGUA + ';border-radius:3px;height:14px;width:100%">'
      + '<div style="background:' + VINHO + ';border-radius:3px;height:14px;width:' + pct + '%"></div>'
      + '</div></td>'
      + '<td style="padding:7px 12px;font-size:12px;color:' + AZUL + ';font-weight:700;text-align:right;'
      + 'white-space:nowrap;font-family:' + FONTE + '">' + linha.qtd + '</td>'
      + '</tr>';
  }
  secDias = faixaSecao('Volume por dia', AZUL)
    + '<tr><td style="padding:0 32px">'
    + '<table width="100%" cellpadding="0" cellspacing="0" style="border:1.6px solid ' + BORDA + ';'
    + 'border-top:none;border-radius:0 0 12px 12px;background:' + BRANCO + ';padding:6px 0">'
    + rowsDias + '</table></td></tr>';
}

// --- Reincidentes (3+ dias na semana) --------------------------------------
const recids = d.recidivistas || [];
let secRecid = '';
if (recids.length > 0) {
  let rowsR = '';
  for (const r of recids) {
    rowsR += '<tr>'
      + td(r.placa, 'left', AZUL, '700')
      + td(r.modelo || '—', 'left')
      + td(badgeOrigem(r.provedor), 'center')
      + td(r.diasAtivos + 'd / ' + r.totalAlertas + 'x', 'center', AZUL, '700')
      + td(fmtDec(r.velMax) + ' km/h', 'right', corVelocidade(r.velMax), '700')
      + '</tr>';
  }
  secRecid = faixaSecao('Reincidentes · alertas em 3 ou mais dias', CRITICO)
    + tabela(th('Placa') + th('Modelo') + th('Origem', 'center')
           + th('Dias / Alertas', 'center') + th('Pico', 'right'), rowsR);
}

// --- Top 10 e Top 15 (mesmas tabelas do diario) ----------------------------
let rowsTop = '';
for (const o of (d.topOcorrencias || [])) {
  const v = o.velocidade || 0;
  const modelo = (d.tabelaPlacas || []).find(x => x.placa === o.placa)?.modelo || '—';
  rowsTop += '<tr>'
    + td(o.placa, 'left', AZUL, '700')
    + td(modelo, 'left')
    + td(badgeOrigem(o.origem), 'center')
    + td(fmtDec(v) + ' km/h', 'right', corVelocidade(v), '700')
    + td(o.data || '—', 'left')
    + td(o.local || o.cidade || '—', 'left')
    + '</tr>';
}

let rowsPlacas = '';
for (const p of (d.tabelaPlacas || [])) {
  const v = p.velMax || 0;
  rowsPlacas += '<tr>'
    + td(p.placa, 'left', AZUL, '700')
    + td(p.modelo || '—', 'left')
    + td(badgeOrigem(p.provedor), 'center')
    + td(fmtNum(p.qtd), 'center')
    + td(fmtDec(v) + ' km/h', 'right', corVelocidade(v), '700')
    + '</tr>';
}

// --- Documento --------------------------------------------------------------
const html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">'
+ '<meta name="viewport" content="width=device-width,initial-scale=1.0">'
+ '<link href="https://fonts.googleapis.com/css2?family=Roboto+Condensed:wght@400;600;700&display=swap" rel="stylesheet">'
+ '</head><body style="margin:0;padding:0;background:' + FUNDO + ';font-family:' + FONTE + '">'

+ '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';padding:28px 0">'
+ '<tr><td align="center">'
+ '<table width="700" cellpadding="0" cellspacing="0" style="max-width:700px;width:100%;'
+ 'background:' + BRANCO + ';border:1.6px solid ' + BORDA + ';border-radius:12px">'

+ '<tr><td style="padding:24px 32px 18px;border-bottom:3px solid ' + VINHO + '">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ '<td valign="middle" width="140" style="padding-right:22px">'
+ '<img src="' + LOGO_ESCURA + '" width="128" style="display:block;width:128px;height:auto" alt="Grupo Gritsch">'
+ '</td>'
+ '<td valign="middle">'
+ '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">Torre de Controle</div>'
+ '<div style="font-size:23px;font-weight:600;color:' + AZUL + ';margin-top:4px">Relatório Semanal de Velocidade</div>'
+ '<div style="font-size:13px;color:' + CINZA + ';margin-top:3px">' + (d.filial || '—') + '</div>'
+ '</td>'
+ '<td valign="middle" align="right">'
+ '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">Semana</div>'
+ '<div style="font-size:13px;color:' + CINZA + ';margin-top:6px">' + (d.dataRef || '—') + '</div>'
+ '</td>'
+ '</tr></table></td></tr>'

+ '<tr><td style="padding:24px 24px 4px">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ boxKpi('Eventos na semana', fmtNum(d.totalEventos), '', AZUL)
+ boxKpi('Velocidade máxima', fmtDec(d.velMax), 'km/h', (d.velMax >= 120 ? ALERTA : AZUL))
+ boxKpi('Velocidade média', fmtDec(d.velMedia), 'km/h', AZUL)
+ '</tr></table></td></tr>'

+ boxResumo
+ secRecid
+ secDias

+ faixaSecao('Top 10 ocorrências mais graves')
+ tabela(th('Placa') + th('Modelo') + th('Origem', 'center')
       + th('Velocidade', 'right') + th('Data/hora') + th('Local'), rowsTop)

+ faixaSecao('Alertas por placa (Top 15)')
+ tabela(th('Placa') + th('Modelo') + th('Origem', 'center')
       + th('Qtd', 'center') + th('Pico', 'right'), rowsPlacas)

+ '<tr><td style="padding:24px 32px;background:' + AZUL + ';border-radius:0 0 10px 10px">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ '<td valign="middle">'
+ '<img src="' + LOGO_BRANCA + '" width="110" style="display:block;width:110px;height:auto" alt="Gritsch">'
+ '</td>'
+ '<td valign="middle" align="right" style="font-size:11px;color:' + BRANCO + ';line-height:1.7">'
+ 'Relatório automático da Torre de Controle · semanal<br>'
+ 'Fontes: 3STEC, Nuxeo e Omnilink · somente filiais com 5+ eventos na semana<br>'
+ 'torredecontrole@gritsch.com.br'
+ '</td>'
+ '</tr></table></td></tr>'

+ '</table></td></tr></table></body></html>';

return [{ json: { ...d, htmlEmail: html } }];

var filiais = $('11S - Agrupar por Filial + KPIs').all();
var dataRef = $('01S - Calcular Periodo Semanal').first().json.dataRef;
if (filiais.length === 0 || (filiais.length === 1 && filiais[0].json._semEventos)) {
  return [{ json: { _semEventos: true, dataRef: dataRef, totalFiliais: 0,
    totalEventosGeral: 0, velMaxGeral: 0, velMediaGeral: 0,
    rankingFiliais: [], piorOfensorGeral: null, recidivistasGeral: [] } }];
}
var totalEventosGeral = 0, velMaxGeral = 0, somaVelMedia = 0, countVelMedia = 0;
var rankingFiliais = [], piorOfensorGeral = null, recidivistasGeral = [];
for (var i = 0; i < filiais.length; i++) {
  var f = filiais[i].json;
  if (f._semEventos) continue;
  totalEventosGeral += (f.totalEventos || 0);
  if ((f.velMax || 0) > velMaxGeral) velMaxGeral = f.velMax;
  if (f.velMedia > 0) { somaVelMedia += f.velMedia * f.totalEventos; countVelMedia += f.totalEventos; }
  var topPlaca = (f.tabelaPlacas && f.tabelaPlacas[0]) || null;
  rankingFiliais.push({
    filial: f.filial, totalEventos: f.totalEventos || 0, velMax: f.velMax || 0,
    velMedia: f.velMedia || 0, qtdPlacasEnvolvidas: (f.tabelaPlacas || []).length,
    qtdRecidivistas: (f.recidivistas || []).length,
    topPlaca: topPlaca ? { placa: topPlaca.placa, modelo: topPlaca.modelo || '',
      qtd: topPlaca.qtd, velMax: topPlaca.velMax } : null
  });
  if (topPlaca && (!piorOfensorGeral || topPlaca.qtd > piorOfensorGeral.qtd)) {
    piorOfensorGeral = { placa: topPlaca.placa, modelo: topPlaca.modelo || '',
      qtd: topPlaca.qtd, velMax: topPlaca.velMax, filial: f.filial };
  }
  var recids = f.recidivistas || [];
  for (var ri = 0; ri < recids.length; ri++) {
    recidivistasGeral.push(Object.assign({}, recids[ri], { filial: f.filial }));
  }
}
rankingFiliais.sort(function(a,b){ return b.totalEventos - a.totalEventos; });
recidivistasGeral.sort(function(a,b){ return b.diasAtivos - a.diasAtivos || b.totalAlertas - a.totalAlertas; });
var velMediaGeral = countVelMedia > 0 ? Math.round((somaVelMedia / countVelMedia) * 100) / 100 : 0;
return [{ json: { dataRef: dataRef, totalFiliais: rankingFiliais.length,
  totalEventosGeral: totalEventosGeral, velMaxGeral: velMaxGeral, velMediaGeral: velMediaGeral,
  rankingFiliais: rankingFiliais, piorOfensorGeral: piorOfensorGeral,
  recidivistasGeral: recidivistasGeral,
  consolidadoDestinatarios: filiais[0] && filiais[0].json && filiais[0].json.consolidadoDestinatarios ? filiais[0].json.consolidadoDestinatarios : 'jefferson@gritsch.com.br',
  consolidadoCC: filiais[0] && filiais[0].json && filiais[0].json.consolidadoCC ? filiais[0].json.consolidadoCC : 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br',
  _semEventos: false } }];

// ===========================================================================
// 16S - Gerar HTML Geral Semanal  (identidade visual Grupo Gritsch, v1.0)
//
// Mesma paleta e componentes de "Gerar HTML Geral" (diario). Ver aquele
// arquivo para o mapeamento secao-a-secao do design system.
//
// UMA SECAO A MAIS: "Reincidentes globais" (d.recidivistasGeral), que so faz
// sentido numa janela de 7 dias — cada linha ja vem com a filial anexada
// pelo node 15S.
//
// CORRIGIDO em relacao a versao anterior deste node: o rodape dizia "Fonte:
// Nuxeo" e "acima de 180 km/h removido por erro de sensor" — texto de uma
// fase anterior do projeto, antes da 3S e da Omnilink entrarem e antes do
// teto de plausibilidade virar por classe de veiculo (ver
// silver/23_plausibilidade_velocidade.sql). Alinhado ao rodape do diario.
// ===========================================================================

const d = $json;

const fmtNum = (n) => String(n ?? 0).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmtDec = (n) => String(n ?? 0).replace('.', ',');

const AZUL = '#213035', VINHO = '#8E2E2F', ALERTA = '#FA1126', CRITICO = '#5A181C';
const ATENCAO = '#E8A33D', POSITIVO = '#13880D', CINZA = '#4E4D4D';
const BORDA = '#BFBFBF', REGUA = '#E2E2E2', FUNDO = '#F2F2F2', BRANCO = '#FFFFFF';

const FONTE = "'Roboto Condensed','Arial Narrow',Arial,sans-serif";

const LOGO_ESCURA = 'https://gritsch.com.br/wp-content/uploads/2022/03/logomarca-1_gritsch-1.png';
const LOGO_BRANCA = 'https://gritsch.com.br/wp-content/uploads/2023/07/logo_branca1080.png';

const corVelocidade = (v) => (v >= 140 ? CRITICO : v >= 120 ? ALERTA : ATENCAO);

// Destinatarios do consolidado, vindos do node 11S/15S — que por sua vez lê
// torre.email_gritsch_config (chaves consolidado_destinatarios/consolidado_cc).
const emailDestinoConsolidado = d.consolidadoDestinatarios || 'jefferson@gritsch.com.br';
const emailCCConsolidado = d.consolidadoCC || 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br';

const abre = () =>
  '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1.0">'
  + '<link href="https://fonts.googleapis.com/css2?family=Roboto+Condensed:wght@400;600;700&display=swap" rel="stylesheet">'
  + '</head><body style="margin:0;padding:0;background:' + FUNDO + ';font-family:' + FONTE + '">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';padding:28px 0">'
  + '<tr><td align="center">'
  + '<table width="760" cellpadding="0" cellspacing="0" style="max-width:760px;width:100%;'
  + 'background:' + BRANCO + ';border:1.6px solid ' + BORDA + ';border-radius:12px">';

const rodape = () =>
  '<tr><td style="padding:24px 32px;background:' + AZUL + ';border-radius:0 0 10px 10px">'
  + '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td valign="middle">'
  + '<img src="' + LOGO_BRANCA + '" width="120" style="display:block;width:120px;height:auto" alt="Gritsch">'
  + '</td>'
  + '<td valign="middle" align="right" style="font-size:11px;color:' + BRANCO + ';line-height:1.7">'
  + 'Relatório automático da Torre de Controle · semanal<br>'
  + 'Fontes: 3STEC, Nuxeo e Omnilink · somente filiais com 5+ eventos na semana<br>'
  + 'torredecontrole@gritsch.com.br'
  + '</td></tr></table></td></tr>'
  + '</table></td></tr></table></body></html>';

const cabecalho = (subtitulo) =>
  '<tr><td style="padding:24px 32px 18px;border-bottom:3px solid ' + VINHO + '">'
  + '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td valign="middle" width="140" style="padding-right:22px">'
  + '<img src="' + LOGO_ESCURA + '" width="128" style="display:block;width:128px;height:auto" alt="Grupo Gritsch">'
  + '</td>'
  + '<td valign="middle">'
  + '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">Torre de Controle</div>'
  + '<div style="font-size:23px;font-weight:600;color:' + AZUL + ';margin-top:4px">Visão Geral Semanal</div>'
  + '<div style="font-size:13px;color:' + CINZA + ';margin-top:3px">' + subtitulo + '</div>'
  + '</td>'
  + '<td valign="middle" align="right">'
  + '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">Semana</div>'
  + '<div style="font-size:13px;color:' + CINZA + ';margin-top:6px">' + (d.dataRef || '—') + '</div>'
  + '</td></tr></table></td></tr>';

// ---------------------------------------------------------------------------
// Semana sem filial com volume relevante (nenhuma bateu o minimo de 5
// eventos). Unico lugar do relatorio onde o verde e correto (regra 5.3).
// ---------------------------------------------------------------------------
if (d._semEventos) {
  const vazio = abre()
    + cabecalho('Consolidado de todas as filiais')
    + '<tr><td style="padding:44px 32px;text-align:center">'
    + '<table cellpadding="0" cellspacing="0" align="center" style="background:' + FUNDO + ';'
    + 'border-left:4px solid ' + POSITIVO + ';border-radius:0 8px 8px 0">'
    + '<tr><td style="padding:18px 28px;text-align:left">'
    + '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + POSITIVO + '">Dentro da meta</div>'
    + '<div style="font-size:20px;font-weight:600;color:' + AZUL + ';margin-top:6px">Nenhuma filial com volume relevante na semana</div>'
    + '<div style="font-size:13px;color:' + CINZA + ';margin-top:6px">Nenhuma filial atingiu o mínimo de 5 eventos nesta semana.</div>'
    + '</td></tr></table></td></tr>'
    + rodape();
  return [{ json: { ...d, htmlEmail: vazio, emailDestino: emailDestinoConsolidado, emailCC: emailCCConsolidado } }];
}

// --- KPI ------------------------------------------------------------------
const boxKpi = (rotulo, valor, unidade, corNumero) =>
  '<td width="25%" valign="top" style="padding:0 6px">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + BRANCO + ';'
  + 'border:1.6px solid ' + BORDA + ';border-radius:12px"><tr><td style="padding:14px 18px">'
  + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:' + CINZA + ';'
  + 'font-family:' + FONTE + '">' + rotulo + '</div>'
  + '<div style="font-size:26px;font-weight:700;color:' + (corNumero || AZUL) + ';margin-top:4px;'
  + 'font-family:' + FONTE + '">' + valor
  + (unidade ? '<span style="font-size:12px;font-weight:400;color:' + CINZA + '"> ' + unidade + '</span>' : '')
  + '</div></td></tr></table></td>';

// --- Pior ofensor (lider da semana) ----------------------------------------
let boxPior = '';
if (d.piorOfensorGeral) {
  const p = d.piorOfensorGeral;
  const cor = corVelocidade(p.velMax);
  const nivel = p.velMax >= 140 ? 'Crítico' : p.velMax >= 120 ? 'Alto' : 'Moderado';
  boxPior = '<tr><td style="padding:22px 32px 0">'
    + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';'
    + 'border-left:4px solid ' + cor + ';border-radius:0 8px 8px 0"><tr><td style="padding:16px 22px">'
    + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">'
    + 'Veículo líder na semana · nível ' + nivel + '</div>'
    + '<div style="font-size:15px;color:' + CINZA + ';margin-top:8px;line-height:1.7">'
    + '<span style="font-weight:700;color:' + AZUL + ';font-size:17px">' + p.placa + '</span>'
    + ' · ' + (p.modelo || '—') + ' · ' + (p.filial || '—') + '<br>'
    + '<span style="font-weight:700;color:' + AZUL + '">' + fmtNum(p.qtd) + '</span> alertas na semana'
    + ' · pico de <span style="font-weight:700;color:' + cor + '">' + fmtDec(p.velMax) + ' km/h</span>'
    + '</div></td></tr></table></td></tr>';
}

const th = (txt, align) =>
  '<th style="padding:10px 12px;text-align:' + (align || 'left') + ';font-size:12px;font-weight:700;'
  + 'text-transform:uppercase;color:' + BRANCO + ';background:' + VINHO + ';font-family:' + FONTE + '">' + txt + '</th>';

const td = (c, align, cor, peso) =>
  '<td style="padding:10px 12px;border-bottom:1.6px solid ' + REGUA + ';font-size:13px;'
  + 'text-align:' + (align || 'left') + ';color:' + (cor || CINZA) + ';font-weight:' + (peso || '400') + ';'
  + 'font-family:' + FONTE + '">' + c + '</td>';

const faixaSecao = (titulo, corFaixa) =>
  '<tr><td style="padding:26px 32px 0"><table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td style="background:' + (corFaixa || VINHO) + ';border-radius:10px 10px 0 0;padding:9px 20px;'
  + 'font-size:14px;font-weight:700;color:' + BRANCO + ';font-family:' + FONTE + '">' + titulo + '</td>'
  + '</tr></table></td></tr>';

// --- Reincidentes globais (Top 20, ja vem cortado do node 15S) ------------
const rg = (d.recidivistasGeral || []).slice(0, 20);
let secRecidGeral = '';
if (rg.length > 0) {
  let rowsR = '';
  for (const r of rg) {
    rowsR += '<tr>'
      + td(r.placa, 'left', AZUL, '700')
      + td(r.modelo || '—', 'left')
      + td(r.filial || '—', 'left')
      + td(r.diasAtivos + 'd / ' + r.totalAlertas + 'x', 'center', AZUL, '700')
      + td(fmtDec(r.velMax) + ' km/h', 'right', corVelocidade(r.velMax), '700')
      + '</tr>';
  }
  secRecidGeral = faixaSecao('Reincidentes globais · 3 ou mais dias', CRITICO)
    + '<tr><td style="padding:0 32px">'
    + '<table width="100%" cellpadding="0" cellspacing="0" style="border:1.6px solid ' + BORDA + ';'
    + 'border-top:none;border-radius:0 0 12px 12px;background:' + BRANCO + '">'
    + '<tr>' + th('Placa') + th('Modelo') + th('Filial') + th('Dias / Alertas', 'center') + th('Pico', 'right') + '</tr>'
    + rowsR + '</table></td></tr>';
}

// --- Ranking de filiais ------------------------------------------------
let rowsFiliais = '', pos = 1;
for (const f of (d.rankingFiliais || [])) {
  const topInfo = f.topPlaca ? f.topPlaca.placa + ' (' + f.topPlaca.qtd + 'x)' : '—';
  const recidLabel = f.qtdRecidivistas > 0 ? f.qtdRecidivistas + ' reincid.' : '—';
  rowsFiliais += '<tr>'
    + td(pos, 'center', BORDA, '700')
    + td(f.filial, 'left', AZUL, '700')
    + td(fmtNum(f.totalEventos), 'center')
    + td(f.qtdPlacasEnvolvidas, 'center')
    + td(recidLabel, 'center', f.qtdRecidivistas > 0 ? CRITICO : CINZA, f.qtdRecidivistas > 0 ? '700' : '400')
    + td(fmtDec(f.velMax) + ' km/h', 'right', corVelocidade(f.velMax), '700')
    + td(topInfo, 'left')
    + '</tr>';
  pos++;
}

const html = abre()
  + cabecalho('Consolidado de todas as filiais · ' + fmtNum(d.totalFiliais) + ' com 5+ eventos')
  + '<tr><td style="padding:24px 26px 4px"><table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + boxKpi('Eventos na semana', fmtNum(d.totalEventosGeral), '', AZUL)
  + boxKpi('Filiais', fmtNum(d.totalFiliais), '', AZUL)
  + boxKpi('Velocidade máxima', fmtDec(d.velMaxGeral), 'km/h', (d.velMaxGeral >= 120 ? ALERTA : AZUL))
  + boxKpi('Velocidade média', fmtDec(d.velMediaGeral), 'km/h', AZUL)
  + '</tr></table></td></tr>'
  + boxPior
  + secRecidGeral
  + faixaSecao('Ranking de filiais (mínimo 5 eventos)')
  + '<tr><td style="padding:0 32px">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="border:1.6px solid ' + BORDA + ';'
  + 'border-top:none;border-radius:0 0 12px 12px;background:' + BRANCO + '">'
  + '<tr>' + th('#', 'center') + th('Filial') + th('Eventos', 'center')
  + th('Placas', 'center') + th('Reincid.', 'center') + th('Pico', 'right') + th('Top alertas') + '</tr>'
  + rowsFiliais + '</table></td></tr>'
  + rodape();

return [{ json: { ...d, htmlEmail: html, emailDestino: emailDestinoConsolidado, emailCC: emailCCConsolidado } }];
